// Bounded evidence packer. Node.js builtins only; no dependencies.
//
// API: packContext(sections, maxBytes) -> {text, bytes, included, omitted}
// CLI: node context-packet.js INPUT_JSON_FILE
//
// The exact serialized frame for one section is:
//   '### ' + JSON.stringify(section.id) + '\n' + section.text + '\n'
// Its cost is Buffer.byteLength(frame, 'utf8'). Frames are indivisible:
// never shortened, never normalized, always whole.

import {readFileSync, realpathSync} from 'node:fs';
import {fileURLToPath, pathToFileURL} from 'node:url';

function invalid(message) {
  throw new Error(message);
}

function isSectionObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function validateMaxBytes(maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) {
    invalid('maxBytes must be a nonnegative safe integer');
  }
}

function validateSections(sections) {
  if (!Array.isArray(sections)) {
    invalid('sections must be an array');
  }
  for (let i = 0; i < sections.length; i++) {
    if (!(i in sections)) {
      invalid(`sections[${i}] is missing`);
    }
  }
  const seenIds = new Set();
  for (let i = 0; i < sections.length; i++) {
    const section = sections[i];
    if (!isSectionObject(section)) {
      invalid(`sections[${i}] must be a non-null, non-array object`);
    }
    const {id, text, priority, required} = section;
    if (typeof id !== 'string' || id.length === 0) {
      invalid(`sections[${i}].id must be a nonempty string`);
    }
    if (typeof text !== 'string') {
      invalid(`sections[${i}].text must be a string`);
    }
    if (!Number.isSafeInteger(priority) || priority < 0) {
      invalid(`sections[${i}].priority must be a nonnegative safe integer`);
    }
    if (typeof required !== 'boolean') {
      invalid(`sections[${i}].required must be a boolean`);
    }
    if (seenIds.has(id)) {
      invalid(`duplicate section id: ${JSON.stringify(id)}`);
    }
    seenIds.add(id);
  }
}

function frameFor(section) {
  return '### ' + JSON.stringify(section.id) + '\n' + section.text + '\n';
}

export function packContext(sections, maxBytes) {
  // Validate the entire input before packing anything, even when the budget
  // is zero or a section would be omitted.
  validateMaxBytes(maxBytes);
  validateSections(sections);

  const frames = new Array(sections.length);
  const costs = new Array(sections.length);
  for (let i = 0; i < sections.length; i++) {
    frames[i] = frameFor(sections[i]);
    costs[i] = Buffer.byteLength(frames[i], 'utf8');
  }

  // 1. All required sections first, in original input order; priority is
  //    ignored for them. Overflow throws instead of returning a partial set.
  const includedIndex = [];
  let used = 0;
  for (let i = 0; i < sections.length; i++) {
    if (!sections[i].required) continue;
    used += costs[i];
    if (used > maxBytes) {
      throw new Error('required sections exceed maxBytes');
    }
    includedIndex.push(i);
  }

  // 2. Optional sections by descending priority, ties by original input
  //    order. Include when the whole frame fits; otherwise skip and continue.
  const optional = [];
  for (let i = 0; i < sections.length; i++) {
    if (!sections[i].required) optional.push(i);
  }
  optional.sort((a, b) => {
    const delta = sections[b].priority - sections[a].priority;
    return delta !== 0 ? delta : a - b;
  });
  for (const i of optional) {
    if (costs[i] <= maxBytes - used) {
      includedIndex.push(i);
      used += costs[i];
    }
  }

  // 3. Output in inclusion order; omitted optional IDs in input order.
  const text = includedIndex.map((i) => frames[i]).join('');
  const included = includedIndex.map((i) => sections[i].id);
  const includedSet = new Set(includedIndex);
  const omitted = [];
  for (let i = 0; i < sections.length; i++) {
    if (!sections[i].required && !includedSet.has(i)) {
      omitted.push(sections[i].id);
    }
  }

  return {text, bytes: used, included, omitted};
}

function runCli() {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    process.stderr.write('usage: node context-packet.js INPUT_JSON_FILE\n');
    process.exitCode = 2;
    return;
  }
  let result;
  try {
    const raw = readFileSync(args[0], 'utf8');
    const data = JSON.parse(raw);
    result = packContext(data.sections, data.maxBytes);
  } catch (err) {
    process.stderr.write(String(err && err.message ? err.message : err) + '\n');
    process.exitCode = 2;
    return;
  }
  process.stdout.write(JSON.stringify(result) + '\n');
}

// Run the CLI only when this file is the main module, never on import.
// Compare realpaths so symlinked invocations still match.
const invokedDirectly = (() => {
  try {
    const entry = process.argv[1];
    if (typeof entry !== 'string' || entry.length === 0) return false;
    const entryUrl = pathToFileURL(realpathSync(entry)).href;
    const selfUrl = pathToFileURL(realpathSync(fileURLToPath(import.meta.url))).href;
    return entryUrl === selfUrl;
  } catch {
    return false;
  }
})();

if (invokedDirectly) {
  runCli();
}

