+const cost = (id, text) =>
+  Buffer.byteLength('### ' + JSON.stringify(id) + '\n' + text + '\n', 'utf8');
+
+test('maxBytes must be a nonnegative safe integer', () => {
+  const good = [sec('a', 't', 0, true)];
+  for (const bad of [-1, 0.5, -0.5, NaN, Infinity, -Infinity, 2 ** 53, '100', null, undefined, true, 1n]) {
+    assert.throws(() => packContext(good, bad), Error);
+  }
+  for (const ok of [0, 1, 2 ** 53 - 1]) {
+    assert.doesNotThrow(() => packContext([], ok));
+  }
+});
+
+test('sections container and slots are validated', () => {
+  for (const bad of ['nope', null, undefined, {}, new Set(), 42]) {
+    assert.throws(() => packContext(bad, 10), Error);
+  }
+  // Sparse holes are invalid.
+  const sparse = [sec('a', 't')];
+  sparse.length = 3;
+  assert.throws(() => packContext(sparse, 10), Error);
+  const deleted = [sec('a', 't'), sec('b', 'u')];
+  delete deleted[0];
+  assert.throws(() => packContext(deleted, 10), Error);
+});
+
+test('section values are strict, unknown fields ignored', () => {
+  const good = (over) => [sec('a', 't', 0, false, over)];
+  for (const bad of [null, [], 's', 42, undefined, () => {}]) {
+    assert.throws(() => packContext([bad], 10), Error);
+  }
+  const base = {id: 'a', text: 't', priority: 0, required: false};
+  const badValues = [
+    {id: ''}, {id: 5}, {id: null}, {id: true},
+    {text: 5}, {text: null}, {text: undefined}, {text: ['t']},
+    {priority: -1}, {priority: 1.5}, {priority: '3'}, {priority: NaN},
+    {priority: null}, {priority: true}, {priority: 2 ** 53},
+    {required: 'yes'}, {required: 0}, {required: 1}, {required: null},
+  ];
+  for (const fields of badValues) {
+    assert.throws(() => packContext([Object.assign({}, base, fields)], 10),
+      Error, JSON.stringify(fields));
+  }
+  // Missing-field objects used as-is (not merged into a valid base).
+  for (const obj of [{}, {text: 't'}, {id: 'a'}, {id: 'a', text: 't'},
+    {id: 'a', text: 't', priority: 0}]) {
+    assert.throws(() => packContext([obj], 10), Error, JSON.stringify(obj));
+  }
+  // Unknown fields are ignored and must not affect the result.
+  const withExtra = [sec('a', 't', 0, false, {bogus: {deep: [1, 2]}})];
+  assert.deepEqual(packContext(withExtra, 10), {
+    text: '### "a"\nt\n', bytes: cost('a', 't'), included: ['a'], omitted: [],
+  });
+});
+
+test('IDs are unique exact strings; odd names are valid', () => {
+  assert.throws(() => packContext([sec('x', 'a'), sec('x', 'b')], 100), Error);
+  // Case is significant: 'x' and 'X' are distinct.
+  assert.deepEqual(packContext([sec('x', 'a'), sec('X', 'b')], 100).included, ['x', 'X']);
+  const weird = ['__proto__', ' ', 'a b', 'a\nb', 'a\u0000b', 'ключ', '雪'];
+  for (const id of weird) {
+    const res = packContext([sec(id, 't')], 1000);
+    assert.deepEqual(res, {
+      text: '### ' + JSON.stringify(id) + '\nt\n',
+      bytes: cost(id, 't'), included: [id], omitted: [],
+    });
+  }
+  // No prototype pollution from odd IDs: __proto__ unchanged, no new own props.
+  assert.equal(Object.prototype.__proto__, null);
+  for (const id of weird.filter((id) => id !== '__proto__')) {
+    assert.ok(!Object.prototype.hasOwnProperty(id), id);
+  }
+});
+
+test('validation runs fully before packing, even on zero budget or omission', () => {
+  // Required overflow AND invalid optional: must still throw.
+  assert.throws(() => packContext(
+    [sec('big', 'x'.repeat(100), 0, true), sec('bad', 'y', 'nope')], 0), Error);
+  // Invalid entry that would be omitted: still throws.
+  assert.throws(() => packContext(
+    [sec('ok', 't', 5), sec('bad', 't', 1.5)], 100), Error);
+  // Duplicate id detected even though the second copy would not be included.
+  assert.throws(() => packContext(
+    [sec('dup', 't', 9), sec('dup', 'x'.repeat(1000), 0)], 10), Error);
+});
+
+test('required sections come first in input order, overflow throws', () => {
+  const sections = [
+    sec('opt-low', 'l', 1),
+    sec('opt-high', 'h', 99),
+    sec('req', 'r', 50, true),
+  ];
+  const res = packContext(sections, 100);
+  assert.deepEqual(res.included, ['req', 'opt-high', 'opt-low']);
+  assert.equal(res.omitted.length, 0);
+  assert.equal(res.bytes, cost('req', 'r') + cost('opt-high', 'h') + cost('opt-low', 'l'));
+  assert.equal(
+    res.text,
+    '### "req"\nr\n### "opt-high"\nh\n### "opt-low"\nl\n',
+  );
+
+  const requiredCost = cost('req', 'r');
+  assert.doesNotThrow(() => packContext(sections, requiredCost + 200));
+  assert.throws(() => packContext(sections.slice(0, 1).concat(sec('req', 'r', 50, true)), requiredCost - 1), Error);
+  // Exact fit on the required total alone is allowed.
+  const exact = packContext(sections, requiredCost);
+  assert.deepEqual(exact.included, ['req']);
+  assert.deepEqual(exact.omitted, ['opt-low', 'opt-high']);
+});
+
+test('optional order is descending priority, ties by input order', () => {
+  const sections = [sec('a', 'x', 5), sec('b', 'y', 5), sec('c', 'z', 9)];
+  assert.deepEqual(packContext(sections, 1000).included, ['c', 'a', 'b']);
+  assert.deepEqual(packContext(sections, 20).included, ['c', 'a']);
+});
+
+test('omitted optionals are reported in input order, skip continues', () => {
+  // Priority order is b(9), c(5), a(1); budget only fits c.
+  const sections = [
+    sec('a', 'a'.repeat(200), 1),
+    sec('b', 'b'.repeat(200), 9),
+    sec('c', 'c', 5),
+  ];
+  const res = packContext(sections, cost('c', 'c'));
+  assert.deepEqual(res.included, ['c']);
+  assert.deepEqual(res.omitted, ['a', 'b']);
+
+  // A too-large section is skipped, later smaller ones still tried.
+  const skip = [
+    sec('big1', 'x'.repeat(100), 10),
+    sec('mid', 'mm', 5),
+    sec('small', 's', 4),
+  ];
+  const fit = cost('mid', 'mm') + cost('small', 's');
+  assert.deepEqual(packContext(skip, fit), {
+    text: '### "mid"\nmm\n### "small"\ns\n',
+    bytes: fit, included: ['mid', 'small'], omitted: ['big1'],
+  });
+});
+
+test('exact fits and zero budget behavior', () => {
+  const a = sec('a', 'aa', 3);
+  const b = sec('b', 'bb', 3);
+  const total = cost('a', 'aa') + cost('b', 'bb');
+  assert.deepEqual(packContext([a, b], total).included, ['a', 'b']);
+  assert.deepEqual(packContext([a, b], total - 1).omitted, ['b']);
+
+  assert.deepEqual(packContext([sec('z', 't', 9)], 0), {
+    text: '', bytes: 0, included: [], omitted: ['z'],
+  });
+  assert.throws(() => packContext([sec('z', 't', 0, true)], 0), Error);
+});
+
+test('UTF-8 byte counting, empty input, no mutation', () => {
+  const frame = '### "雪"\né\n';
+  assert.deepEqual(packContext([sec('雪', 'é', 0)], Buffer.byteLength(frame, 'utf8')), {
+    text: frame, bytes: Buffer.byteLength(frame, 'utf8'), included: ['雪'], omitted: [],
+  });
+
+  assert.deepEqual(packContext([], 0), {text: '', bytes: 0, included: [], omitted: []});
+  assert.deepEqual(packContext([], 999), {text: '', bytes: 0, included: [], omitted: []});
+
+  const frozen = Object.freeze([Object.freeze(sec('f', 't', 1, true, {extra: 1}))]);
+  const before = JSON.stringify([sec('f', 't', 1, true, {extra: 1})]);
+  const res = packContext(frozen, 100);
+  assert.deepEqual(res.included, ['f']);
+  assert.equal(JSON.stringify(frozen), before);
+});
+
+test('CLI behavior', () => {
+  const cli = join(dirname(fileURLToPath(import.meta.url)), '..', 'context-packet.js');
+  const dir = mkdtempSync(join(tmpdir(), 'context-packet-'));
+  test.after(() => rmSync(dir, {recursive: true, force: true}));
+  const file = (name, content) => {
+    const p = join(dir, name);
+    writeFileSync(p, content, 'utf8');
+    return p;
+  };
+  const run = (...args) => spawnSync(process.execPath, [cli, ...args], {encoding: 'utf8'});
+  const expectFail = (r) => {
+    assert.equal(r.status, 2);
+    assert.ok(r.stderr.length > 0, 'stderr must be nonempty');
+    assert.equal(r.stdout, '', 'no stdout on failure');
+    assert.equal(r.error, undefined);
+  };
+
+  const input = file('ok.json', JSON.stringify({
+    sections: [
+      {id: 'req', text: 'Do it.', priority: 0, required: true},
+      {id: 'opt', text: 'x', priority: 7, required: false},
+    ],
+    maxBytes: 100,
+    extra: 'ignored',
+  }));
+  const ok = run(input);
+  assert.equal(ok.status, 0, ok.stderr);
+  assert.equal(ok.stderr, '');
+  const expected = {
+    text: '### "req"\nDo it.\n### "opt"\nx\n',
+    bytes: cost('req', 'Do it.') + cost('opt', 'x'),
+    included: ['req', 'opt'], omitted: [],
+  };
+  assert.equal(ok.stdout, JSON.stringify(expected) + '\n');
+
+  // Importing the module must not run the CLI: the file above was read as
+  // data, and the test file itself imports packContext without side effects.
+  expectFail(run());
+  expectFail(run(input, input));
+  expectFail(run(join(dir, 'missing.json')));
+  expectFail(run(file('bad.json', '{nope')));
+  expectFail(run(file('nonobj.json', '42')));
+  expectFail(run(file('null.json', 'null')));
+  expectFail(run(file('badapi.json', JSON.stringify({sections: [{id: 'a', text: 't', priority: 0, required: false}], maxBytes: '100'}))));
+  expectFail(run(file('overflow.json', JSON.stringify({sections: [{id: 'a', text: 't', priority: 0, required: true}], maxBytes: 0}))));
+});

files.before:
import test from 'node:test';
import assert from 'node:assert/strict';
import {packContext} from '../context-packet.js';
const section=(id,text,priority=0,required=false)=>({id,text,priority,required});
test('required evidence is included before optional priority',()=>{
  assert.deepEqual(packContext([section('extra','x',50),section('rule','Do it.',0,true)],100),{
    text:'### "rule"\nDo it.\n### "extra"\nx\n',bytes:32,included:['rule','extra'],omitted:[]});
});
test('whole UTF-8 sections, exact fits, and skip instead of stop',()=>{
  const frame='### "雪"\né\n',bytes=Buffer.byteLength(frame);
  assert.deepEqual(packContext([section('large','x'.repeat(100),10),section('雪','é',1)],bytes),{
    text:frame,bytes,included:['雪'],omitted:['large']});
});
test('empty selection and required overflow',()=>{
  assert.deepEqual(packContext([],0),{text:'',bytes:0,included:[],omitted:[]});
  assert.throws(()=>packContext([section('rule','x',0,true)],0),Error);
});
test('validate omitted entries too and leave input unchanged',()=>{
  assert.throws(()=>packContext([section('x','x'),section('x','y')],0),Error);
  assert.throws(()=>packContext(new Array(1),0),Error);
  const input=[section('b','b',1),section('a','a',1)],before=JSON.stringify(input);
  assert.deepEqual(packContext(input,100).included,['b','a']);
  assert.equal(JSON.stringify(input),before);
});

